import 'package:flutter/material.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:sehatak/core/services/child_service.dart';class ChildGrowthTrackerScreen extends StatefulWidget{const ChildGrowthTrackerScreen({super.key});@override State<ChildGrowthTrackerScreen>createState()=>_S();}class _S extends State<ChildGrowthTrackerScreen>{DateTime?birth;final h=TextEditingController(),w=TextEditingController();bool busy=false;Future<void>pick()async{final d=await showDatePicker(context:context,firstDate:DateTime(2010),lastDate:DateTime.now(),initialDate:birth??DateTime.now());if(d!=null)setState(()=>birth=d);}Future<void>save()async{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('سجل الدخول أولاً')));return;}setState(()=>busy=true);try{final s=ChildService();if(birth!=null)await s.updateBirthDate(uid,birth!);await s.updateGrowth(uid,height:double.tryParse(h.text),weight:double.tryParse(w.text));if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم حفظ بيانات النمو')));}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){h.dispose();w.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('متابعة نمو الطفل')),body:ListView(padding:const EdgeInsets.all(20),children:[Card(child:ListTile(leading:const Icon(Icons.cake,color:Color(0xFF00BCD4)),title:Text(birth==null?'اختر تاريخ الميلاد':'الميلاد: ${birth!.day}/${birth!.month}/${birth!.year}'),onTap:pick)),const SizedBox(height:12),TextField(controller:h,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الطول (سم)',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:w,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الوزن (كجم)',border:OutlineInputBorder())),const SizedBox(height:16),ElevatedButton(onPressed:busy?null:save,child:Text(busy?'جارٍ الحفظ...':'حفظ القياسات')),const SizedBox(height:20),const Text('التطعيمات الأساسية',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17)),const Text('عند الولادة: BCG + HepB\n2 أشهر: DPT + Polio + Hib\n4 أشهر: DPT + Polio\n6 أشهر: DPT + Polio + HepB\n12 شهر: MMR\n18 شهر: DPT booster') ]));}}
